import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { QTYPES } from '../api/_shared';
import { CONTS, type Country, type Region } from '../src/config';
import { buildQuestion, canAsk, type Ctx } from '../src/questions';

// Generated by `npm run data` (the build runs it before the tests).
const all: Country[] = JSON.parse(readFileSync(new URL('../public/data/countries.json', import.meta.url), 'utf8'));
const byC = Object.fromEntries(all.map(d => [d.c, d]));

describe('question builders', () => {
  for (const reg of ['all', ...CONTS] as Region[]) {
    it(`every askable question in "${reg}" has 4 distinct options including the answer`, () => {
      const ctx: Ctx = { all, byC, pool: all.filter(d => reg === 'all' || d.k === reg), reg };
      for (let rep = 0; rep < 3; rep++) for (const t of ctx.pool) for (const type of QTYPES) {
        if (!canAsk(type, t, ctx)) continue;
        const q = buildQuestion(type, t, ctx);
        if (type === 'find') { expect(q.opts).toHaveLength(0); continue; }
        expect(q.opts, `${type} ${t.n}`).toHaveLength(4);
        expect(new Set(q.opts.map(o => o.label)).size, `${type} ${t.n} labels`).toBe(4);
        expect(q.opts.some(o => o.c === q.target.c), `${type} ${t.n} answer`).toBe(true);
      }
    });
  }

  it('area question targets the largest of the four', () => {
    const ctx: Ctx = { all, byC, pool: all, reg: 'all' };
    const q = buildQuestion('area', byC.CZE!, ctx);
    expect(Math.max(...q.opts.map(o => byC[o.c]!.a))).toBe(q.target.a);
  });

  it('neighbour question answers with a real neighbour', () => {
    const ctx: Ctx = { all, byC, pool: all, reg: 'all' };
    const q = buildQuestion('nb', byC.CZE!, ctx);
    expect(byC.CZE!.b).toContain(q.target.c);
    expect(q.about.c).toBe('CZE');
  });
});
